from django.db import migrations, models

LOTE = 500
RUC_CONSUMIDOR_FINAL = '9999999999'


def copiar_nombre_del_cliente(apps, schema_editor):
    """Copia cliente.nombre a nombre_cliente en las ventas que aún no lo tienen.

    El consumidor final es una sola fila compartida entre empresas: su nombre
    actual es el de la última empresa que vendió. Para esas ventas se usa el
    texto de consumidor final de la propia empresa de la venta.
    """
    Venta = apps.get_model('ventas', 'Venta')
    ConfiguracionFactura = apps.get_model('ventas', 'ConfiguracionFactura')
    texto_por_empresa = {
        empresa_id: (texto or '').strip() or 'CONSUMIDOR FINAL'
        for empresa_id, texto in ConfiguracionFactura.objects.values_list('empresa_id', 'texto_consumidor_final')
    }
    pendientes = Venta.objects.filter(nombre_cliente='').select_related('cliente')

    # Lotes por pk: así no se escribe mientras hay un cursor abierto sobre la misma tabla.
    ultimo_pk = 0
    while True:
        lote = list(pendientes.filter(pk__gt=ultimo_pk).order_by('pk')[:LOTE])
        if not lote:
            break
        for venta in lote:
            if venta.cliente.ruc_cedula == RUC_CONSUMIDOR_FINAL:
                venta.nombre_cliente = texto_por_empresa.get(venta.empresa_id, 'CONSUMIDOR FINAL')
            else:
                venta.nombre_cliente = venta.cliente.nombre
        Venta.objects.bulk_update(lote, ['nombre_cliente'])
        ultimo_pk = lote[-1].pk


